"""LDS_16653: three chained MaxPool2d(kernel=2, stride=2) on NCHW input."""
import jax
import jax.numpy as jnp
from jax import lax

CONFIG = {
    'name': 'LDS_16653',
    'batch': 16,
    'channels': 64,
    'height': 256,
    'width': 256,
    'pool_kernel': 2,
    'pool_stride': 2,
    'num_pools': 3,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype=dtype,
    )
    return (x,)


def _maxpool2d(x):
    k = CONFIG['pool_kernel']
    s = CONFIG['pool_stride']
    return lax.reduce_window(
        x, -jnp.inf, lax.max, (1, 1, k, k), (1, 1, s, s), 'VALID'
    )


def workload(x):
    for _ in range(CONFIG['num_pools']):
        x = _maxpool2d(x)
    return x

"""[bf16 variant] AutoEncoder: 4x(conv3x3+relu+maxpool2 ceil) -> conv+relu -> nearest up(75) -> 3x(conv+relu+nearest up x2) -> conv3x3."""
import jax
import jax.numpy as jnp
from jax import lax

CONFIG = {
    'name': 'AutoEncoder_10195',
    'batch': 32,
    'in_channels': 3,
    'height': 512,
    'width': 512,
    'encoder_channels': (3, 16, 8, 4, 4),
    'decoder_channels': (4, 4, 4, 8, 16, 3),
    'kernel_size': 3,
    'padding': 1,
    'pool_size': 2,
    'up1_size': 75,
    'up_scale': 2,
}


def _layer_shapes():
    k = CONFIG['kernel_size']
    shapes = []
    for chans in (CONFIG['encoder_channels'], CONFIG['decoder_channels']):
        for cin, cout in zip(chans[:-1], chans[1:]):
            shapes.append(((cout, cin, k, k), (cout,)))
    return shapes


def create_inputs(dtype=jnp.bfloat16):
    shapes = _layer_shapes()
    key = jax.random.key(0)
    keys = jax.random.split(key, 1 + 2 * len(shapes))
    x = jax.random.uniform(
        keys[0],
        (CONFIG['batch'], CONFIG['in_channels'], CONFIG['height'], CONFIG['width']),
        dtype,
    )
    params = []
    for i, (w_shape, b_shape) in enumerate(shapes):
        params.append(jax.random.normal(keys[1 + 2 * i], w_shape, dtype) * 0.02)
        params.append(jax.random.normal(keys[2 + 2 * i], b_shape, dtype) * 0.02)
    return (x, *params)


def _conv(x, w, b):
    p = CONFIG['padding']
    y = lax.conv_general_dilated(
        x, w, window_strides=(1, 1), padding=((p, p), (p, p)),
        dimension_numbers=('NHWC', 'OIHW', 'NHWC'),
    )
    return y + b


def _pool_ceil(x):
    # ceil_mode with kernel == stride: pad -inf at the end up to a multiple of k.
    k = CONFIG['pool_size']
    ph = (-x.shape[1]) % k
    pw = (-x.shape[2]) % k
    init = jnp.array(-jnp.inf, x.dtype)
    return lax.reduce_window(
        x, init, lax.max, (1, k, k, 1), (1, k, k, 1),
        ((0, 0), (0, ph), (0, pw), (0, 0)),
    )


def _nearest_idx(in_size, out_size):
    # PyTorch nearest: min(floor(dst * float32(in/out)), in - 1).
    scale = jnp.float32(in_size) / jnp.float32(out_size)
    idx = jnp.floor(jnp.arange(out_size, dtype=jnp.float32) * scale).astype(jnp.int32)
    return jnp.minimum(idx, in_size - 1)


def _resize_nearest(x, size):
    x = jnp.take(x, _nearest_idx(x.shape[1], size), axis=1)
    return jnp.take(x, _nearest_idx(x.shape[2], size), axis=2)


def _upscale(x):
    s = CONFIG['up_scale']
    return jnp.repeat(jnp.repeat(x, s, axis=1), s, axis=2)


def workload(x, *params):
    ws, bs = params[0::2], params[1::2]
    n_enc = len(CONFIG['encoder_channels']) - 1
    h = jnp.transpose(x, (0, 2, 3, 1))
    for i in range(n_enc):
        h = _pool_ceil(jax.nn.relu(_conv(h, ws[i], bs[i])))
    dw, db = ws[n_enc:], bs[n_enc:]
    h = jax.nn.relu(_conv(h, dw[0], db[0]))
    h = _resize_nearest(h, CONFIG['up1_size'])
    for i in range(1, len(dw) - 1):
        h = _upscale(jax.nn.relu(_conv(h, dw[i], db[i])))
    h = _conv(h, dw[-1], db[-1])
    return jnp.transpose(h, (0, 3, 1, 2))

"""BPR-max loss: softmax(dim=1) * sigmoid(diag - logit), mean, -log."""
import jax
import jax.numpy as jnp

CONFIG = {'name': 'BPR_max_2229', 'n': 8192}


def create_inputs(dtype=jnp.float32):
    n = CONFIG['n']
    logit = jax.random.uniform(jax.random.key(0), (n, n), dtype)
    return (logit,)


def workload(logit):
    logit_softmax = jax.nn.softmax(logit, axis=1)
    diff = jnp.diagonal(logit)[:, None] - logit
    return -jnp.log(jnp.mean(logit_softmax * jax.nn.sigmoid(diff)))

"""GatedActivation: chunk(2, dim=1) -> tanh(x) * sigmoid(y)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'GatedActivation_6864',
    'batch': 16,
    'channels': 256,
    'height': 128,
    'width': 128,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype=dtype,
    )
    return (x,)


def workload(x):
    a, b = jnp.split(x, 2, axis=1)
    return jnp.tanh(a) * jax.nn.sigmoid(b)

"""MonotonicMax: per-sample max over H, stacked so the output is (C, B, W)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'MonotonicMax_10863',
    'batch': 16,
    'channels': 128,
    'height': 128,
    'width': 256,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype,
    )
    return (x,)


def workload(x):
    # torch: cat over the batch of max(x[b], dim=1).unsqueeze(1) -> (C, B, W)
    return jnp.transpose(jnp.max(x, axis=2), (1, 0, 2))

"""[bf16 variant] Cast to float32 -> sqrt -> divide by 5.0 -> floor."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'TracedModule_1024',
    'batch': 16,
    'channels': 16,
    'height': 512,
    'width': 512,
    'divisor': 5.0,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    shape = (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width'])
    x = jax.random.uniform(key, shape, dtype=dtype)
    return (x,)


def workload(x):
    x = x.astype(jnp.float32)
    return jnp.floor(jnp.sqrt(x) / CONFIG['divisor'])

